package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"regexp"
	"strings"
	"testing"
)

// simple reference matcher: pattern -> regexp
func patternRegexp(pattern string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(pattern); {
		c := pattern[i]
		if c == ':' {
			j := i + 1
			for j < len(pattern) && pattern[j] != '/' {
				j++
			}
			sb.WriteString("[^/]*")
			i = j
		} else if c == '*' {
			sb.WriteString(".*")
			i++
		} else {
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	sb.WriteString("$")
	return regexp.MustCompile(sb.String())
}

func TestZZTmpInvariant(t *testing.T) {
	rnd := rand.New(rand.NewSource(555))
	for iter := 0; iter < 200000; iter++ {
		nRoutes := rnd.Intn(4) + 1
		routes := make([]string, nRoutes)
		for i := range routes {
			routes[i] = randRoute(rnd)
		}
		path := randRoute(rnd)
		e := New()
		r := e.router
		for _, rt := range routes {
			r.Add(http.MethodGet, rt, func(c Context) error { return nil })
		}
		c := e.NewContext(nil, nil).(*context)
		r.Find(http.MethodGet, path, c)
		if c.path == "" {
			continue // no match
		}
		// matched route must actually match
		re := patternRegexp(c.path)
		if !re.MatchString(path) {
			t.Fatalf("iter=%d routes=%q path=%q matched=%q which does not match path", iter, routes, path, c.path)
		}
	}
	fmt.Println("invariant ok")
}
